import{U as e,W as t,nt as n,t as r}from"./chunks/framework.BPwQCpO3.js";var i=JSON.parse(`{"title":"ADR-0003: Why JSON-RPC over stdio","description":"","frontmatter":{},"headers":[],"relativePath":"adr/ADR-0003-why-jsonrpc-over-stdio.md","filePath":"adr/ADR-0003-why-jsonrpc-over-stdio.md","lastUpdated":1793381793000}`),a={name:`adr/ADR-0003-why-jsonrpc-over-stdio.md`};function o(r,i,a,o,s,c){return n(),e(`div`,null,[...i[0]||=[t(`<h1 id="adr-0003-why-json-rpc-over-stdio" tabindex="-1">ADR-0003: Why JSON-RPC over stdio <a class="header-anchor" href="#adr-0003-why-json-rpc-over-stdio" aria-label="Permalink to “ADR-0003: Why JSON-RPC over stdio”">​</a></h1><ul><li>Status: Accepted</li><li>Date: 2026-10-31</li><li>Related: docs/guide/agent-protocol.md, ADR-0002</li></ul><h2 id="background" tabindex="-1">Background <a class="header-anchor" href="#background" aria-label="Permalink to “Background”">​</a></h2><p>The core and plugin subprocesses need a request/response channel for handshake, capability declaration, probe calls, and recovery actions. It must be zero-barrier for plugin authors and must not widen the attack surface.</p><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to “Decision”">​</a></h2><p>JSON-RPC 2.0 over stdio, newline-delimited (one JSON message per line): stdout carries <strong>only</strong> protocol messages; stderr carries <strong>only</strong> diagnostic logging (never parsed as protocol); requests carry an id and timeout; incomplete lines, malformed JSON, and unknown methods return a clear error instead of crashing; stdout lines have a size cap — over-limit lines are skipped, never fatal; stderr has a dedicated continuously-draining thread with capped tail retention.</p><h2 id="alternatives" tabindex="-1">Alternatives <a class="header-anchor" href="#alternatives" aria-label="Permalink to “Alternatives”">​</a></h2><ul><li><strong>gRPC/protobuf</strong>: strong typing and streaming are good, but code generation toolchains raise the plugin author&#39;s barrier; introduces an HTTP/2 stack — both complexity and attack surface grow.</li><li><strong>HTTP on localhost</strong>: exposes a port (other local processes can access it); lifecycle binding is complex.</li><li><strong>Custom binary protocol</strong>: self-maintained parser, large crash surface, hard to debug.</li></ul><h2 id="pros-and-cons" tabindex="-1">Pros and Cons <a class="header-anchor" href="#pros-and-cons" aria-label="Permalink to “Pros and Cons”">​</a></h2><p>Pros: any language can speak it in three lines; no ports, no network surface; the stdout/stderr semantic boundary makes &quot;protocol polluted by logs&quot; observable and preventable (cap + skip policy). Cons: throughput lower than binary protocols (more than enough for alerting volume); the line protocol requires strict stdout discipline from plugins — so the host must also defensively handle undisciplined plugins.</p><h2 id="follow-up-impact" tabindex="-1">Follow-up Impact <a class="header-anchor" href="#follow-up-impact" aria-label="Permalink to “Follow-up Impact”">​</a></h2><ul><li>session.rs: read loop, deadline, cancellation, output cap, dying-words (crashed session&#39;s stderr tail).</li><li>Outbound requests (host → plugin direction) have a size cap to prevent the host from being tricked into filling a pipe.</li></ul>`,12)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};